//! RIIR 1: the rundown processing contract. Times, gaps, delays and days, as
//! upstream's server computes them (fixture generated by running its
//! makeRundownMetadata), against our Rundown::recompute. These values come
//! from our server and every screen shows them.

use ontime_core::rundown::Rundown;
use serde::Deserialize;
use serde_json::{Map, Value};

#[derive(Deserialize)]
struct Case {
    name: String,
    rundown: Rundown,
    entries: Map<String, Value>,
}

#[derive(Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

const FIELDS: [&str; 6] = [
    "timeStart",
    "timeEnd",
    "duration",
    "gap",
    "delay",
    "dayOffset",
];

#[test]
fn recompute_matches_upstream() {
    let fixture: Fixture =
        serde_json::from_str(include_str!("fixtures/rundown_process.json")).unwrap();
    let mut failures = Vec::new();
    for case in fixture.cases {
        let mut rundown = case.rundown;
        rundown.recompute();
        for (id, want) in &case.entries {
            let kind = want.get("type").and_then(Value::as_str).unwrap_or_default();
            if !matches!(kind, "event" | "group") {
                continue;
            }
            let got = rundown.entries.get(id).cloned().unwrap_or(Value::Null);
            for field in FIELDS {
                let Some(expected) = want.get(field) else {
                    continue;
                };
                let actual = got.get(field).unwrap_or(&Value::Null);
                if actual.as_f64() != expected.as_f64() {
                    failures.push(format!(
                        "{} / {id}.{field}: upstream {expected}, ours {actual}",
                        case.name
                    ));
                }
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
